use super::kit::*;
pub fn commands()->Vec<Command>{vec![Command{name:"transition_render_raw",description:"Software render luma, directional_warp, cross_zoom or displacement. Explicit raw controls, progress0..1 and clamp/repeat/transparent edge. A/B straight RGBA buffers in matching declared color domains; bilinear filtering/blending premultiplied internally; finite signed HDR RGB retained. No automatic easing or preset. Returns actual frame pixels, not a project/timeline mutation.",mutates:false,schema:obj(vec![("from",json!({"type":"object"})),("to",json!({"type":"object"})),("map",json!({"type":"object"})),("operator",json!({"type":"object"})),("progress",n("0..1")),("edge",s("clamp|repeat|transparent"))],&["from","to","operator","progress","edge"]),run:|_,a|{
 #[derive(serde::Deserialize)]#[serde(deny_unknown_fields)]struct Buffer{w:usize,h:usize,d:Vec<f32>}
 let frame=|k:&str|->Result<crate::effects::Frame,String>{let b:Buffer=serde_json::from_value(a.get(k).ok_or_else(||format!("{k} required"))?.clone()).map_err(|e|e.to_string())?;Ok(crate::effects::Frame{w:b.w,h:b.h,d:b.d})};
 let from=frame("from")?;let to=frame("to")?;let map=if a.get("map").is_some(){Some(frame("map")?)}else{None};let op=serde_json::from_value(a.get("operator").ok_or("operator required")?.clone()).map_err(|e|e.to_string())?;let edge=serde_json::from_value(a.get("edge").ok_or("edge required")?.clone()).map_err(|e|e.to_string())?;
 let f=crate::transition_raw::render(&from,&to,map.as_ref(),num_arg(a,"progress")?,&op,edge)?;Ok(json!({"w":f.w,"h":f.h,"d":f.d,"alpha":"straight","domain":"caller_declared_matching_inputs"}))
}}]}
